function reportKey(g){return g.id+':'+activeScenario(g)}
function reportFor(g){const r=state.reports?.[reportKey(g)];return r&&typeof r==='object'?r:{}}
function reportSummary(g){const r=reportFor(g);return {configured:r.configuration===true,tested:r.consent===true&&r.action===true&&r.reconnect===true,external:['cleared','not-required'].includes(r.external)}}
function readiness(g){const r=reportFor(g),summary=reportSummary(g);return `<section class="section readiness-gates" id="readiness"><div class="section-heading"><h2>Test & launch status</h2><span class="section-note">Reported by you Â· not automatically verified</span></div><div class="readiness-grid report-grid"><article><span class="gate-number">01</span><h3>Configuration</h3><p class="report-status">${summary.configured?'Completed â€” self-reported':'Not reported complete'}</p><label class="report-check"><input type="checkbox" data-report="configuration" ${r.configuration===true?'checked':''}> I completed the required app configuration.</label></article><article><span class="gate-number">02</span><h3>Connection test</h3><p class="report-status">${summary.tested?'Passed â€” self-reported':'Testing still unresolved'}</p>${[['consent','User consent succeeds'],['action','The intended API action succeeds'],['reconnect','Refresh or reconnection works']].map(([key,label])=>`<label class="report-check"><input type="checkbox" data-report="${key}" ${r[key]===true?'checked':''}> ${label}</label>`).join('')}</article><article><span class="gate-number">03</span><h3>External access</h3><p class="report-status">${summary.external?'Cleared â€” self-reported':'Unresolved'}</p><label class="report-select">Approval or customer-policy check<select data-report="external"><option value="unresolved" ${!summary.external?'selected':''}>Still unresolved</option><option value="cleared" ${r.external==='cleared'?'selected':''}>Required access / approval obtained</option><option value="not-required" ${r.external==='not-required'?'selected':''}>Confirmed no approval is required</option></select></label><p>Confirm provider requirements and the target customerâ€™s workspace policy. An internal test does not establish external access.</p></article></div><p class="section-intro">These are your recorded checks, separate from the setup checklist. They do not certify a working connection or completed provider approval. Reports stay in this browser; Markdown exports include them.${g.assessment&&!g.assessment.canGenerate?' Core evidence is still incomplete; resolve it before relying on the setup path.':''}</p></section>`}
function audienceLabel(value){return ({testing:'Just me / testing',organization:'My organization',customers:'External customers'})[value]||'External customers (assumed)'}
function coveragePanel(g){if(!g.assessment)return '';const a=g.assessment;return `<section class="coverage-panel ${a.canGenerate?'':'incomplete'}"><div><span class="meta-label">EVIDENCE COVERAGE</span><h2>${g.kind==='managed-check'?'Managed-app fit still needs checking':a.canGenerate?'Core setup evidence located':'Setup path not established'}</h2><p>${g.kind==='research-gap'?'This is an investigation checklist, not a ready-to-follow registration guide. Complete the missing research before configuring OAuth.':a.note}</p></div><ul>${a.checks.map(c=>`<li>${ico(c.located?'file':'alert',14)}<span>${esc(c.label)}</span><strong>${c.id==='external'&&!c.required?'Future launch check':c.located?'Text located':'Not established'}</strong>${c.url?`<a href="${esc(url(c.url))}" target="_blank" rel="noreferrer">Source ${ico('arrow',12)}</a>`:''}</li>`).join('')}</ul></section>`}
function decisionSource(g,topic){const mapping={github:{permissions:1,external:2},box:{permissions:5,external:1},gmail:{permissions:0,external:activeScenario(g)==='send'?4:5},linear:{permissions:0,external:1}};const source=g.sources[mapping[g.id]?.[topic]];if(source)return `<a class="source-link" href="${esc(url(source.url))}" target="_blank" rel="noreferrer">${esc(topic==='permissions'?'Permission reference':'Access / verification reference')} ${ico('arrow',12)}</a>`;const check=g.assessment?.checks.find(c=>c.id===topic);return check?.url?`<a class="source-link" href="${esc(url(check.url))}" target="_blank" rel="noreferrer">Retrieved ${topic==='permissions'?'permission':'access'} evidence Â· audit required ${ico('arrow',12)}</a>`:'<span class="muted">Source support not established</span>'}

function activeScenario(g){return state.scenarios?.[g.id]||(g.id==='box'?'contents':g.id==='gmail'?'inbox':'default')}
function progressKey(g,i){return g.id+':'+activeScenario(g)+':'+i}
function effectiveGuide(base){const g=structuredClone(base),choice=activeScenario(g);if(g.id==='box'){g.goal=choice==='metadata'?'Browse file and folder information':'Read document contents';g.scopeText=choice==='metadata'?'root_readonly':'root_readwrite (document downloads)';g.steps[3].body=choice==='metadata'?'Use root_readonly for file and folder read access. Access is still restricted by the authorizing user\'s permissions. This path does not establish document-download readiness.':'Box\'s current scope reference says root_readwrite is necessary to download files and folders. That grant also permits writes; expose only the operations your assistant needs. This mapping is documented, not endpoint-tested.';}else if(g.id==='gmail'){g.goal=choice==='send'?'Send email on the user\'s behalf':'Read the user\'s inbox';g.scopeText=choice==='send'?'gmail.send - sensitive':'gmail.readonly - restricted';g.wait=choice==='send'?'Google publishes a typical 3-5-business-day sensitive-scope review estimate; preparation and rework are additional.':'Restricted-scope review can take several weeks; assessment requirements depend on data handling and applicable exceptions.';g.steps[0].body=choice==='send'?'This scenario uses gmail.send, a sensitive scope. Do not add inbox access unless the feature needs it. Check verification exceptions and the current scope reference.':'This scenario uses gmail.readonly, a restricted scope. Read-only access can still trigger restricted-scope verification and applicable security assessment requirements.';if(choice==='send')g.steps=g.steps.filter((_,i)=>i!==5);}else if(g.id==='github'){g.goal='Connect external users and access permitted GitHub resources';g.scopeText='Choose scopes for the intended GitHub API actions';}else{g.goal=g.goal||g.requestContext?.purpose||'Confirm the intended use before choosing scopes';g.scopeText=g.scopeText||'Confirm minimum scopes against the cited API reference';}return g}
function scenarioBar(g){return `<section class="scenario-bar" aria-label="Guide context"><div class="scenario-copy"><span class="meta-label">YOUR USE CASE</span><strong>${esc(g.goal)}</strong><span>${['box','gmail','github'].includes(g.id)?audienceLabel(g.requestContext?.audience)+' Â· '+(g.requestContext?.authRoute==='managed'?'Managed app requested':'Custom app path'):audienceLabel(g.requestContext?.audience)+' Â· See assumptions below'}</span><button class="text-link scenario-edit" data-action="adapt-guide">Change audience or auth route</button></div>${['box','gmail'].includes(g.id)?`<label class="scenario-select-label">What should your app do?<select id="scenario-select" aria-label="Intended action">${(g.id==='box'?[['contents','Read document contents'],['metadata','Browse file information']]:[['inbox','Read inbox'],['send','Send email']]).map(([v,label])=>`<option value="${v}" ${activeScenario(g)===v?'selected':''}>${label}</option>`).join('')}</select></label>`:`<span class="scenario-type">${g.kind==='research-gap'?'OAuth support unconfirmed':g.kind==='managed-check'?'Managed coverage unverified':g.id==='github'?'OAuth App':'User-delegated OAuth'}<small>${g.id==='github'?'GitHub Apps follow a separate path':'Validate the audience and scope assumptions'}</small></span>`}</section>`}

function stepHelp(i){state.previousFocus=document.activeElement;const g=effectiveGuide(state.selected),step=g.steps[i];if(!step)return;state.helpIndex=i;const likely=g.blockers.filter(b=>b.source===step.source);const contextual=/permission|scope/i.test(step.title)?g.blockers.filter(b=>/file|scope|permission/i.test(b.symptom)):[];const checks=g.id==='box'&&i===0?[{symptom:'I cannot reach the Developer Console',action:'Use the official free developer signup or sign-in route. For a new account, finish CAPTCHA and email activation. Account verification needs your interaction; it is not provider OAuth approval.',owner:'Account owner',source:4}]:likely.length?likely:contextual.length?contextual:g.blockers;$('#modal-root').innerHTML=`<div class="modal-overlay help-overlay"><section class="modal help-modal" role="dialog" aria-modal="true" aria-labelledby="helper-title"><button class="close" data-action="close" aria-label="Close help">${ico('x',20)}</button><span class="eyebrow">${esc(g.name)} Â· STEP ${i+1}</span><h2 id="helper-title">${esc(step.title)}</h2><p class="modal-description">Use these checks to identify the blocker and the person who can resolve it.</p><div class="help-current"><span class="meta-label">EXPECTED RESULT</span><p>${esc(step.success||'The intended action works in your test account.')}</p></div><h3 class="helper-section-title">Source-linked recovery checks</h3>${checks.map((b,n)=>`<details class="blocker" ${n===0?'open':''}><summary>${ico('alert',16)}<span>${esc(b.symptom)}</span>${ico('chevron',15)}</summary><div><p>${rich(b.action)}</p><div class="blocker-footer"><span class="owner">${esc(b.owner)}</span>${sourceLink(g,b.source)}</div></div></details>`).join('')}<div class="help-handoff"><span class="meta-label">WHO ACTS NEXT</span><p>${esc(step.owner)}. An agent can interpret requirements and prepare checks. The relevant person must complete login, consent, or external approval.</p></div><div class="modal-bottom"><button class="secondary" data-step-handoff="${i}">Prepare a handoff</button><button class="primary" data-action="close">Back to the checklist ${ico('right',15)}</button></div></section></div>`;$('#modal-root .close').focus();$('#modal-root .modal-overlay').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal()});}

const state={selected:null,view:'library',query:'',filter:'All apps',custom:[],done:{},configured:null,busy:false,scenarios:{},reports:{}};
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M7 17 17 7M7 7h10v10',right:'M5 12h14m-6-6 6 6-6 6',left:'M19 12H5m6-6-6 6 6 6',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',x:'m6 6 12 12M6 18 18 6',book:'M4 3h7v17H4zm9 0h7v17h-7',shield:'m12 3 8 4v6c0 4-8 8-8 8S4 17 4 13V7zm-4 9 3 3 5-6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',file:'M6 3h9l4 4v14H6zm8 0v5h5M9 12h7m-7 4h7',link:'m10 14 4-4M8 16l-2 2a4 4 0 0 1-6-6l4-4m12 0 2-2a4 4 0 0 1 6 6l-4 4',alert:'M12 8v5m0 3v1m0-15L1 21h22z',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',chevron:'m9 5 7 7-7 7',circle:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',loader:'M22 12A10 10 0 1 1 12 2'};
const ico=(name,size=16,cl='')=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="${cl}" aria-hidden="true"><path d="${paths[name]||paths.circle}"/></svg>`;
const url=v=>{try{const u=new URL(v);return u.protocol==='https:'?u.href:'#'}catch{return '#'}};
function valid(g){return g&&(!g.kind||['research-gap','managed-check'].includes(g.kind))&&(!g.assessment||Array.isArray(g.assessment.checks)&&g.assessment.checks.every(c=>c&&typeof c.id==='string'&&typeof c.label==='string'&&typeof c.located==='boolean'&&(!c.url||typeof c.url==='string')))&&['id','name','category','initials','summary','difficulty','effort','wait','audience','checked','status','observation','next','managed'].every(k=>typeof g[k]==='string')&&['prerequisites','agent','human','uncertainty'].every(k=>Array.isArray(g[k])&&g[k].every(x=>typeof x==='string'))&&Array.isArray(g.steps)&&g.steps.every(s=>s&&typeof s.title==='string'&&typeof s.body==='string'&&typeof s.owner==='string'&&Number.isInteger(s.source))&&Array.isArray(g.blockers)&&g.blockers.every(b=>b&&typeof b.symptom==='string'&&typeof b.action==='string'&&typeof b.owner==='string'&&Number.isInteger(b.source))&&Array.isArray(g.sources)&&g.sources.every(s=>s&&typeof s.title==='string'&&typeof s.url==='string')}
const icon=(g,large=false)=>`<span class="app-icon ${large?'large':''}" style="background:${/^#[a-f0-9]{6}$/i.test(g.color)?g.color:'#456346'}">${esc(g.initials.slice(0,3))}</span>`;
const sourceLink=(g,i)=>g.sources[i]?`<a class="source-link" href="${esc(url(g.sources[i].url))}" target="_blank" rel="noreferrer">${ico('file',12)} ${esc(g.sources[i].title)} ${ico('arrow',12)}</a>`:'<span class="muted">Unverified â€” confirm before proceeding</span>';
const all=()=>[...GUIDES,...state.custom];
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('Browser storage is unavailable. Export this guide to keep it.')}}
try{state.custom=JSON.parse(localStorage.getItem('atlas-guides')||'[]').filter(valid).slice(0,30);const progress=JSON.parse(localStorage.getItem('atlas-progress')||'{}');state.done=progress&&typeof progress==='object'&&!Array.isArray(progress)?progress:{}}catch{}
try{const reports=JSON.parse(localStorage.getItem('atlas-readiness')||'{}');state.reports=reports&&typeof reports==='object'&&!Array.isArray(reports)?reports:{}}catch{}
function shell(){const saved=state.filter==='My research'&&!state.selected;$('#app').innerHTML=`<a class="skip-link" href="#main-content">Skip to content</a><div class="shell"><header class="app-header"><div class="header-inner"><button class="brand" data-action="home" aria-label="OAuth Atlas home"><span class="brandmark">${ico('link',20)}</span><span>OAuth Atlas<span class="brand-caption">Integration setup guides</span></span></button><nav aria-label="Main navigation"><button data-action="home" class="${state.view==='library'&&!saved?'active':''}">App library</button><button data-action="saved" class="${saved?'active':''}">My guides <span class="nav-count">${state.custom.length}</span></button><button data-action="evidence" class="${state.view==='evidence'?'active':''}">Evidence & method</button></nav><button class="primary header-research" data-action="research">${ico('plus',16)} Research an app</button></div></header><main id="main-content"><div id="page"></div></main></div><div id="modal-root"></div><div id="toast-root" aria-live="polite"></div>`;document.querySelectorAll('.app-header nav button').forEach(b=>b.setAttribute('aria-current',b.classList.contains('active')?'page':'false'));if(state.selected)guidePage(state.selected);else if(state.view==='evidence')evidencePage();else libraryPage();document.title=state.selected?`${state.selected.name} OAuth setup | OAuth Atlas`:'OAuth Atlas | Integration setup guides'}

function libraryPage(){$('#page').innerHTML=`<div class="content"><section class="library-intro"><div><span class="eyebrow">OAUTH APP SETUP</span><h1>Know the path before you build.</h1><p>Registration, permissions, and approval requirements.<br class="desktop-break"> Find the guide for your app, then work through it step by step.</p></div><div class="library-scope"><strong>${GUIDES.length} researched examples</strong><span>Source links and open questions included.</span><button class="text-link" data-action="evidence">How to read the evidence ${ico('right',14)}</button></div></section><section class="library-browser" aria-label="Provider guides"><div class="search-row"><label class="search-label" for="search">Find a provider<span class="search">${ico('search',19)}<input id="search" type="search" value="${esc(state.query)}" placeholder="Search by app name, e.g. Box or Gmail" aria-label="Search provider guides"><kbd>/</kbd></span></label><span class="search-hint">Not listed? Research it from a name<br>or a developer-documentation URL.</span></div><div class="tabs" role="group" aria-label="Filter guides">${['All apps','Review or admin','Needs verification','My research'].map(t=>`<button data-filter="${t}" aria-pressed="${state.filter===t}" class="${state.filter===t?'selected':''}">${esc(t==='My research'?'My guides':t)}</button>`).join('')}</div><div class="library-heading"><h2 id="library-section-title">${state.filter==='My research'?'Your saved guides':'Provider guides'}</h2><span id="result-count" aria-live="polite"></span></div><div class="cards" id="cards"></div></section><section class="research-callout"><span class="callout-symbol">${ico('search',22)}</span><div><h2>Need a different app?</h2><p>Give the researcher a provider and intended action. It reads public documentation and returns a guide with sources and explicit gaps.</p></div><button class="secondary" data-action="research">Research an app ${ico('right',16)}</button></section><footer><span>Guidance for app setup. A working connection still needs testing.</span><button data-action="evidence">Evidence & limitations ${ico('arrow',14)}</button></footer></div>`;renderCards();$('#search').addEventListener('input',e=>{state.query=e.target.value;renderCards()})}

function renderCards(){const found=all().filter(g=>(g.name+' '+g.category).toLowerCase().includes(state.query.toLowerCase())&&(state.filter==='All apps'||state.filter==='My research'&&state.custom.includes(g)||state.filter==='Review or admin'&&['Admin-dependent','Review-heavy'].includes(g.difficulty)||state.filter==='Needs verification'&&g.difficulty==='Unconfirmed'));$('#library-section-title').textContent=state.filter==='My research'?'Your saved guides':'Provider guides';document.querySelectorAll('.app-header nav button').forEach(b=>{const active=state.filter==='My research'?b.dataset.action==='saved':b.dataset.action==='home';b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false')});$('#result-count').textContent=`${found.length} ${found.length===1?'guide':'guides'}`;$('#cards').innerHTML=found.map(g=>`<button class="app-card" data-guide="${esc(g.id)}"><div class="card-top">${icon(g)}<div><h3>${esc(g.name)}</h3><span class="category">${esc(g.category)}</span></div><span class="card-open" aria-hidden="true">${ico('right',18)}</span></div><p>${esc(g.summary)}</p><div class="card-requirement">${ico(g.difficulty==='Unconfirmed'?'alert':'file',15)}<span>${esc(({box:'Customer admin may need to enable the app',gmail:'Verification depends on the requested scopes',github:'Organization policy can restrict access',linear:'External-user requirements need confirmation'})[g.id]||g.difficulty)}</span></div><div class="card-meta"><span><span class="meta-label">Setup effort</span><strong>${esc(g.effort)}</strong></span><span class="status-tag ${/draft|unverified/i.test(g.status)?'draft':''}">${ico(/draft/i.test(g.status)?'file':'book',13)}${esc(g.status)}</span></div><div class="card-footer">Open setup guide ${ico('right',14)}</div></button>`).join('')||`<div class="empty">${ico('search',28)}<h3>${state.filter==='My research'?'No saved guides match':'No guide matches this search'}</h3><p>${state.filter==='My research'?'Guides you generate are saved in this browser.':'Research a new provider from its name or public documentation URL.'}</p><button class="primary" data-action="research">Research ${state.query?esc(state.query):'an app'} ${ico('right',16)}</button></div>`}

function nextStepPanel(g){const completed=g.steps.filter((_,i)=>state.done[progressKey(g,i)]).length,index=g.steps.findIndex((_,i)=>!state.done[progressKey(g,i)]),step=g.steps[index],report=reportSummary(g);return `<section class="next-step-panel" aria-label="Next action"><span class="eyebrow">${g.kind==='research-gap'?'NEXT INVESTIGATION':step?'YOUR NEXT STEP':'CHECKLIST COMPLETE'}</span><h2>${step?esc(step.title):'Validate before launch'}</h2><p>${step?esc(step.where||'Follow the provider instructions in this step.'):'You have marked every step complete. Confirm the consent flow, intended API action, and customer access before launch.'}</p>${step?stepDestination(step):''}${step?`<div class="next-owner">${ico('circle',14)}<span>${esc(step.owner)}</span></div>`:''}<button class="primary full" data-action="${step?'start-setup':'readiness'}">${step?`Go to step ${index+1}`:'Review launch checks'} ${ico('right',16)}</button><div class="checklist-progress"><span>${completed} of ${g.steps.length} steps marked complete</span><progress max="${g.steps.length}" value="${completed}" aria-label="Checklist progress"></progress><small>Progress is recorded by you, not automatically verified.</small></div><div class="launch-summary"><h3>Your reported status</h3><p><span>Configuration</span><strong>${report.configured?'Reported complete':'Not reported'}</strong></p><p><span>Connection test</span><strong>${report.tested?'Reported passed':'Unresolved'}</strong></p><p><span>External access</span><strong>${report.external?'Reported cleared':'Unresolved'}</strong></p><a href="#readiness" data-scroll="readiness">Review or update these checks ${ico('right',13)}</a></div></section>`}
function rich(value){return esc(value).replace(/```(?:[a-z]+)?\n?([\s\S]*?)```/g,'<pre><code>$1</code></pre>').replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\n/g,'<br>')}
function guidePage(base){const g=effectiveGuide(base),completed=g.steps.filter((_,i)=>state.done[progressKey(g,i)]).length,current=g.steps.findIndex((_,i)=>!state.done[progressKey(g,i)]);$('#page').innerHTML=`<div class="guide-page"><div class="page-breadcrumb"><button data-action="home">App library</button>${ico('chevron',13)}<span>${esc(g.name)}</span></div><header class="guide-heading"><div class="guide-title">${icon(g,true)}<div><span class="category">${esc(g.category)}</span><h1>${esc(g.name)} OAuth setup</h1></div></div><div class="actions"><button class="secondary" data-action="share">${ico('link',15)} Copy link</button><button class="secondary" data-action="export">${ico('download',15)} Export guide</button></div></header><p class="guide-summary">${esc(g.summary)}</p><div class="verification-line"><span class="status-tag ${/draft|unverified/i.test(g.status)?'draft':''}">${ico('file',14)}${esc(g.status)}</span><span>${g.kind?'Investigated':/draft/i.test(g.status)?'Generated':'Reviewed'} ${esc(g.checked)}</span><a href="#evidence" data-scroll="evidence">${/draft/i.test(g.status)?'Audit the sources':'Sources & open questions'} ${ico('arrow',13)}</a></div><div class="guide-layout"><div class="guide-main">${scenarioBar(g)}${coveragePanel(g)}<div class="metrics"><div><span class="meta-label">SETUP EFFORT</span><strong>${esc(g.effort)}</strong><small>Planning estimate Â· not measured</small></div><div><span class="meta-label">EXTERNAL WAIT</span><strong>${esc(g.wait)}</strong><small>Separate from setup. Unknown waits still need confirmation.</small>${decisionSource(g,'external')}</div><div><span class="meta-label">WHAT MAY ADD WORK</span><strong>${esc(g.id==='box'?'Customer enterprise policy may require administrator enablement.':g.id==='gmail'?'Your requested scopes determine the verification path.':g.id==='github'?'Organization policy may require owner approval.':g.difficulty==='Unconfirmed'?'External-user requirements still need confirmation.':g.difficulty)}</strong></div></div><section class="route-choice"><div>${ico('link',18)}<div><h2>First, check whether you need your own OAuth app.</h2><p>Composio may offer a managed app. Confirm its permissions and branding fit your use case before registering a custom one.</p></div></div><a href="https://docs.composio.dev/toolkits/managed-auth" target="_blank" rel="noreferrer">Check managed options ${ico('arrow',14)}</a></section><section class="section" id="prerequisites"><div class="section-heading"><h2>Before you start</h2><span class="section-note">Access & prerequisites</span></div><details class="context-detail"><summary>Audience and assumptions</summary><p>${esc(g.audience)}</p></details><div class="scope-note"><span class="meta-label">PERMISSION PATH</span><p>${rich(g.scopeText)}</p>${decisionSource(g,'permissions')}</div><ul class="requirements">${g.prerequisites.map(p=>`<li>${ico('check',16)}<span>${esc(p)}</span></li>`).join('')}</ul></section><section class="section" id="steps"><div class="section-heading"><h2>${g.kind==='research-gap'?'Investigation checklist':g.kind==='managed-check'?'Managed-auth checks':'Setup checklist'}</h2><span id="progress">${completed} / ${g.steps.length} checked by you</span></div><p class="section-intro">Each step shows where to act, who owns it, and what to check before moving on.</p><div class="steps">${g.steps.map((step,i)=>`<article class="step ${state.done[progressKey(g,i)]?'complete':''} ${current===i?'current':''}" id="step-${i}"><div class="step-rail"><button class="step-check" data-step="${i}" aria-label="Mark ${esc(step.title)} complete or incomplete" aria-pressed="${!!state.done[progressKey(g,i)]}">${state.done[progressKey(g,i)]?ico('check',18):`<span>${i+1}</span>`}</button></div><div class="step-content"><div class="step-top"><h3 tabindex="-1">${esc(step.title)}</h3><span class="owner">${esc(step.owner)}</span></div><div class="step-location"><span class="meta-label">WHERE</span><span>${esc(step.where||'Provider console or your integration platform')}</span></div><p class="step-description">${rich(step.body)}</p><div class="completion-check"><span class="meta-label">COMPLETION CHECK</span><p>${esc(step.success||'Verify the intended action in your own test account.')}</p></div><div class="step-tools">${sourceLink(g,step.source)}${stepDestination(step)}<button class="help-trigger" data-help="${i}">${ico('alert',14)} Help with this step</button></div></div></article>`).join('')}</div><p class="readiness-note">${ico('circle',15)} Checking a step records progress. It does not verify a working OAuth connection.</p></section>${readiness(g)}<section class="section" id="blockers"><div class="section-heading"><h2>Blockers & recovery</h2><span class="section-note">What to do if you get stuck</span></div>${g.blockers.map((b,bi)=>`<details class="blocker"><summary>${ico('alert',16)}<span>${esc(b.symptom)}</span>${ico('chevron',15)}</summary><div><p>${rich(b.action)}</p><div class="blocker-footer"><span class="owner">Next owner: ${esc(b.owner)}</span>${sourceLink(g,b.source)}<button class="text-link" data-blocker-handoff="${bi}">Prepare request ${ico('right',13)}</button></div></div></details>`).join('')}</section><section class="section" id="evidence"><div class="section-heading"><h2>Evidence & open questions</h2><span class="section-note">Know what is established</span></div><div class="observation"><span class="meta-label">ACTUAL OBSERVATION</span><p>${esc(g.observation)}</p></div><div class="open-questions"><h3>Still needs verification</h3><ul class="uncertainty">${g.uncertainty.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><details class="context-detail handoff-detail"><summary>What an agent can do Â· Where a person takes over</summary><div class="handoffs"><div><h3>Agent can prepare</h3>${g.agent.map(x=>`<p>${esc(x)}</p>`).join('')}</div><div><h3>Human ownership</h3>${g.human.map(x=>`<p>${esc(x)}</p>`).join('')}</div></div></details><h3 class="sources-title">Supporting sources</h3><div class="sources">${g.sources.map((source,i)=>`<a href="${esc(url(source.url))}" target="_blank" rel="noreferrer"><span class="source-number">${i+1}</span><div><strong>${esc(source.title)}</strong><small>${esc(hostname(source.url))}</small></div>${ico('arrow',16)}</a>`).join('')}</div></section></div><aside class="guide-aside"><div id="next-step-panel">${nextStepPanel(g)}</div><nav class="guide-toc" aria-label="Guide sections"><span class="meta-label">IN THIS GUIDE</span><a href="#prerequisites" data-scroll="prerequisites">Before you start</a><a href="#steps" data-scroll="steps">Setup checklist <span>${g.steps.length}</span></a><a href="#readiness" data-scroll="readiness">Test & launch checks</a><a href="#blockers" data-scroll="blockers">Blockers & recovery</a><a href="#evidence" data-scroll="evidence">Evidence & sources</a></nav><div class="aside-footnote">${ico('shield',16)}<p>${/draft/i.test(g.status)?'This guide is an AI draft. Review its sources before following sensitive or irreversible steps.':'Documentation review is not a completed setup test. Validate with your own account before launch.'}</p></div></aside></div></div>`;$('#scenario-select')?.addEventListener('change',e=>{state.scenarios[g.id]=e.target.value;history.replaceState({},'',location.pathname+'?app='+encodeURIComponent(g.id)+'&scenario='+encodeURIComponent(e.target.value));guidePage(base)})}

function hostname(s){try{return new URL(s).hostname}catch{return 'Unverified URL'}}
function evidencePage(){$('#page').innerHTML=`<div class="content evidence-page"><header class="page-intro"><span class="eyebrow">EVIDENCE & METHOD</span><h1>Know what the guide is based on.</h1><p>Documentation, observations, and successful setup are different levels of evidence. We keep them separate so you can decide what to trust and what to test.</p></header><div class="method-grid">${[{title:'Documented',body:'A requirement supported by linked provider documentation. It can still depend on scopes, account settings, or audience.',icon:'book'},{title:'Observed',body:'An action or blocker actually seen during an investigation. This does not establish that the full OAuth flow works.',icon:'shield'},{title:'Unverified',body:'A gap or account-specific question that still needs a source, a setup attempt, or confirmation from the provider.',icon:'alert'}].map(x=>`<article>${ico(x.icon,22)}<h2>${x.title}</h2><p>${x.body}</p></article>`).join('')}</div><section class="section"><div class="section-heading"><h2>What has actually been checked</h2><span class="section-note">Current example library</span></div><div class="audit-table-wrap"><table class="audit-table"><thead><tr><th scope="col">Provider</th><th scope="col">Evidence</th><th scope="col">Remaining check</th></tr></thead><tbody><tr><th scope="row">Box</th><td>Public signup inspected; console navigation reached sign-in. Setup guidance reviewed against docs.</td><td>No account created, authenticated setup, or OAuth connection tested.</td></tr><tr><th scope="row">Gmail</th><td>Scope and verification requirements reviewed against official docs.</td><td>Consent setup, verification, and actual API use untested.</td></tr><tr><th scope="row">GitHub</th><td>Registration and organization access guidance reviewed against docs.</td><td>No app registration or organization access test performed.</td></tr><tr><th scope="row">Linear</th><td>A live generated draft was audited and manually corrected.</td><td>The original draft failed the content audit. Authenticated setup remains untested.</td></tr></tbody></table></div></section><section class="section"><h2>What the investigations changed</h2><div class="learning"><h3>Start with the intended action.</h3><p>Gmail sending and inbox reading can have different review paths. Box metadata and document downloads can require different grants. A provider name alone is not enough.</p></div><div class="learning"><h3>A citation is not proof that a claim is correct.</h3><p>The Linear draft promoted optional manifests and app-actor authorization to requirements. The reviewed example corrects those errors and preserves the distinction between a live generation and a source audit.</p></div><div class="learning"><h3>A working internal test is a separate milestone.</h3><p>User consent, customer-workspace policy, provider review, and directory listing must be evaluated separately before external launch.</p></div></section><section class="section"><h2>How live research works</h2><ol class="method-steps"><li><strong>Find relevant documentation.</strong><span>Use the provider name or an exact public documentation URL. Discovery may be incomplete or ambiguous.</span></li><li><strong>Build a bounded evidence set.</strong><span>Read a small number of pages and selected excerpts. Source URLs must come from retrieved pages.</span></li><li><strong>Generate a draft, preserving gaps.</strong><span>Separate requirements from estimates and unknowns. Generated guidance still needs a human audit.</span></li></ol><div class="observation"><span class="meta-label">LIMITS TO KEEP IN MIND</span><p>The researcher does not sign in, register provider apps, handle credentials, submit reviews, or prove that a connection works. Local guides can be exported; a localhost link cannot be shared as an externally accessible website.</p></div></section></div>`}

function handoffText(g,kind,index){const item=kind==='blocker'?g.blockers[index]:g.steps[index];if(!item)return '';return ['Subject: Help unblocking '+g.name+' integration setup','','Context: '+g.goal,'Audience: '+audienceLabel(g.requestContext?.audience),'Current blocker / step: '+(item.symptom||item.title),'Requested owner: '+item.owner,'','Please help confirm the requirement or policy preventing this step, and the exact action needed to proceed.','Expected result: '+(item.success||item.action),'Permissions to check: '+g.scopeText,'App ID (if relevant): [add a non-secret app identifier]','Error code / redacted message: [add the actual error]','','Documentation: '+(g.sources[item.source]?.url||'Source not established; please provide the official reference.'),'','Do not include client secrets, access tokens, refresh tokens, or passwords.'].join('\n')}
function openHandoff(kind,index){const g=effectiveGuide(state.selected),text=handoffText(g,kind,index);if(!text)return;state.previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="handoff-title"><button class="close" data-action="close" aria-label="Close handoff">${ico('x',20)}</button><span class="eyebrow">HUMAN HANDOFF</span><h2 id="handoff-title">Prepare an unblock request</h2><p class="modal-description">Review and fill the placeholders before sending it to the relevant owner. Nothing is sent by this app.</p><label class="handoff-label" for="handoff-text">Request draft<textarea id="handoff-text" readonly rows="12">${esc(text)}</textarea></label><div class="modal-bottom"><button class="primary" data-action="copy-handoff">${ico('file',15)} Copy request</button></div></section></div>`;$('#handoff-text').focus();$('#modal-root .modal-overlay').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal()})}
async function copyHandoff(){const field=$('#handoff-text');if(!field)return;try{await navigator.clipboard.writeText(field.value);toast('Request copied. Review it and add the redacted error before sharing.')}catch{field.focus();field.select();toast('Select and copy the request from the text field.')}}
function stepDestination(step){const candidate=step.openUrl||(String(step.where||'').startsWith('https://')?step.where:'');const target=url(candidate);return target!=='#'?`<a class="destination-link" href="${esc(target)}" target="_blank" rel="noreferrer">Open destination ${ico('arrow',13)}</a>`:''}

function modal(){const root=$('#modal-root'),defaults=state.researchDefaults||{};state.researchDefaults=null;state.previousFocus=document.activeElement;root.innerHTML=`<div class="modal-overlay"><section class="modal research-modal" role="dialog" aria-modal="true" aria-labelledby="research-title"><button class="close" data-action="close" aria-label="Close research">${ico('x',20)}</button><span class="eyebrow">NEW PROVIDER GUIDE</span><h2 id="research-title">Map your setup path</h2><p class="modal-description">The right permissions and approval path depend on what you need to do and who will connect.</p><form id="research-form"><label for="app-name">Provider or documentation URL<input name="app" id="app-name" required maxlength="200" value="${esc(state.query)}" placeholder="e.g. Asana or developers.example.com"></label><div class="form-pair"><label for="research-operation">What should your app do?<select id="research-operation" name="operation" required><option value="">Choose an action</option>${[['read','Read information'],['write','Create or update information'],['specific','A specific operation']].map(([v,label])=>`<option value="${v}" ${defaults.operation===v?'selected':''}>${label}</option>`).join('')}</select></label><label for="research-audience">Who needs to connect?<select id="research-audience" name="audience" required><option value="">Choose an audience</option>${[['testing','Just me / testing'],['organization','My organization'],['customers','External customers']].map(([v,label])=>`<option value="${v}" ${defaults.audience===v?'selected':''}>${label}</option>`).join('')}</select></label></div><label for="research-purpose">Describe the intended action <span>Required for a specific operation</span><textarea id="research-purpose" name="purpose" maxlength="1000" rows="2" placeholder="e.g. Read tasks assigned to users across customer workspaces">${esc(defaults.purpose||'')}</textarea></label><label for="research-auth-route">Which OAuth app will you use?<select id="research-auth-route" name="authRoute"><option value="unsure">Help me choose</option><option value="custom" ${defaults.authRoute==='custom'?'selected':''}>My own provider OAuth app</option><option value="managed" ${defaults.authRoute==='managed'?'selected':''}>A Composio managed app</option></select></label><div class="assumption"><span class="meta-label">CHECK BEFORE REGISTERING</span><p>A managed app may cover your use case. <a href="https://docs.composio.dev/toolkits/managed-auth" target="_blank" rel="noreferrer">Check the current directory ${ico('arrow',12)}</a>. Provider coverage, permissions and restrictions still need confirmation.</p></div>${state.configured===false?`<div class="setup-notice">${ico('alert',18)}<div><strong>The researcher is not connected</strong><p>Model access needs to be configured by the site owner. Existing library guides remain available.</p></div></div>`:''}<div id="research-error" role="alert"></div><button class="primary full" type="submit" id="generate" ${state.configured!==true?'disabled':''}>${state.configured===null?'Checking researcherâ€¦':`Investigate setup path ${ico('right',16)}`}</button><p class="modal-foot" id="research-foot" aria-live="polite">Missing core evidence produces an investigation result, not guessed setup instructions.</p></form></section></div>`;$('#app-name').focus();$('#research-form').addEventListener('submit',generate);$('#research-operation').addEventListener('change',e=>{$('#research-purpose').required=e.target.value==='specific'});$('#research-purpose').required=defaults.operation==='specific';root.querySelector('.modal-overlay').addEventListener('click',e=>{if(e.target===e.currentTarget&&!state.busy)closeModal()})}

function closeModal(){if(state.busy){state.requestSeq=(state.requestSeq||0)+1;state.researchAbort?.abort();state.busy=false;}$('#modal-root').innerHTML='';if(state.previousFocus?.isConnected)state.previousFocus.focus();else document.querySelector('[data-action="research"]')?.focus()}
async function generate(e){
 e.preventDefault();if(state.busy||!state.configured)return;
 const form=new FormData(e.target),app=String(form.get('app')||''),purpose=String(form.get('purpose')||''),audience=String(form.get('audience')||'customers'),operation=String(form.get('operation')||'read'),authRoute=String(form.get('authRoute')||'unsure');
 const previous=state.custom.find(g=>g.requestContext?.app?.trim().toLowerCase()===app.trim().toLowerCase()&&(g.requestContext?.purpose||'').trim()===purpose.trim()&&g.requestContext?.audience===audience&&g.requestContext?.operation===operation&&g.requestContext?.authRoute===authRoute);
 if(previous){openGuide(previous);return}
 const token=state.requestSeq=(state.requestSeq||0)+1,controller=new AbortController();state.researchAbort=controller;
 let failed=false;state.busy=true;e.target.setAttribute('aria-busy','true');e.target.querySelectorAll('input,textarea,select').forEach(c=>c.disabled=true);
 $('#generate').disabled=true;$('#generate').innerHTML=ico('loader',17,'spin')+' Reading provider documentationâ€¦';$('#research-error').innerHTML='';$('#research-foot').textContent='Reading sources and building your guide. You can close this dialog to stop waiting.';
 try{
  const response=await fetch('/api/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({app,purpose,audience,operation,authRoute}),signal:controller.signal});
  let result;try{result=await response.json()}catch{throw Error('The server returned an unreadable response. Your saved guides are unaffected.')}
  if(!response.ok)throw Object.assign(new Error(result.error||'Research could not be completed.'),{retryAfter:result.retryAfter,evidenceSaved:result.evidenceSaved,diagnosticRef:result.diagnosticRef});
  if(!valid(result.guide))throw Error('The returned guide is incomplete. It has not been saved.');
  if(state.requestSeq!==token)return;
  state.custom=[result.guide,...state.custom.filter(g=>g.id!==result.guide.id)].slice(0,30);save('atlas-guides',state.custom);state.busy=false;openGuide(result.guide);
 }catch(error){
  if(state.requestSeq!==token||error.name==='AbortError')return;failed=true;
  const wait=Number(error.retryAfter);const timing=Number.isFinite(wait)&&wait>0?`<p>Try again in about ${wait>=60?Math.ceil(wait/60)+' minutes':Math.ceil(wait)+' seconds'}.</p>`:'';
  $('#research-error').innerHTML=`<div class="error"><strong>Guide could not be generated</strong><p>${esc(error.message||'Research failed. Please try again.')}</p>${timing}${error.evidenceSaved?'<p class="error-recovery">Retrieved sources are saved. A retry will reuse them.</p>':''}${error.diagnosticRef?`<small>Error reference: ${esc(error.diagnosticRef)}</small>`:''}</div>`;
 }finally{
  if(state.requestSeq===token){state.busy=false;state.researchAbort=null;const f=$('#research-form');if(f){f.setAttribute('aria-busy','false');f.querySelectorAll('input,textarea,select').forEach(c=>c.disabled=false)}const b=$('#generate');if(b){b.disabled=false;b.innerHTML=(failed?'Try again':'Generate setup guide')+' '+ico('right',16)}const foot=$('#research-foot');if(foot)foot.textContent=failed?'You can edit the provider or intended action before retrying.':'Reads public documentation. Does not create accounts or submit approvals.'}
 }
}
function openGuide(g){state.selected=g;state.view='library';if(GUIDES.some(x=>x.id===g.id))history.pushState({},'',location.pathname+'?app='+encodeURIComponent(g.id)+'&scenario='+encodeURIComponent(activeScenario(g)));else{const packed=btoa(unescape(encodeURIComponent(JSON.stringify(g))));history.pushState({},'',location.pathname+'#guide='+packed)}shell();scrollTo(0,0)}
function home(){state.selected=null;state.view='library';history.pushState({},'',location.pathname);shell();scrollTo(0,0)}
function route(){state.selected=null;state.view='library';const params=new URLSearchParams(location.search);const id=params.get('app');if(id&&params.get('scenario')&&((id==='gmail'&&['send','inbox'].includes(params.get('scenario')))||(id==='box'&&['contents','metadata'].includes(params.get('scenario')))))state.scenarios[id]=params.get('scenario');const g=all().find(x=>x.id===id);if(g)state.selected=g;else if(location.hash.startsWith('#guide=')){try{const hash=location.hash.slice(7);if(hash.length>100000)throw Error();const v=JSON.parse(decodeURIComponent(escape(atob(hash))));if(!valid(v))throw Error();v.status='Shared AI draft';v.observation='Shared guide content supplied through this URL. No provider setup or connection has been tested; audit the linked sources before use.';state.selected=v}catch{setTimeout(()=>toast('This shared guide could not be read.'),10)}}shell()}
function toast(message){let root=$('#toast-root');if(!root)return;root.innerHTML=`<div class="toast" role="status">${ico('check',17)}${esc(message)}</div>`;setTimeout(()=>root.innerHTML='',5000)}
async function share(){try{await navigator.clipboard.writeText(location.href);toast('Link copied. For someone on another computer, use Export guide until the site is hosted.')}catch{toast('Copy the guide URL from your address bar.')}}
function download(){const g=state.selected?effectiveGuide(state.selected):null;if(!g)return;const text=`# ${g.name} OAuth setup guide\n\n${g.summary}\n\nIntended action: ${g.goal}\nPermission path: ${g.scopeText}\nAudience: ${g.audience}\n\nDifficulty: ${g.difficulty}\nEffort estimate (not measured): ${g.effort}\nExternal wait: ${g.wait}\n\n## Next action\n${g.next}\n\n## Prerequisites\n${g.prerequisites.map(x=>'- '+x).join('\n')}\n\n## Setup\n${g.steps.map((s,i)=>`${i+1}. ${s.title}\n${s.body}\nWhere: ${s.where||"Provider console or integration platform"}\nCompletion check: ${s.success||"Test the intended action"}\nOwner: ${s.owner}\nSource: ${g.sources[s.source]?.url||'Unverified'}`).join('\n\n')}\n\n## Blockers\n${g.blockers.map(b=>`${b.symptom}\n${b.action}\nOwner: ${b.owner}`).join('\n\n')}\n\n## Agent can help\n${g.agent.map(x=>'- '+x).join('\n')}\n\n## Human handoff\n${g.human.map(x=>'- '+x).join('\n')}\n\n## Evidence\n${g.observation}\n\n## Uncertainty\n${g.uncertainty.map(x=>'- '+x).join('\n')}\n\n## Your reported status\nConfiguration completed: ${reportSummary(g).configured?'Reported complete':'Not reported'}\nConnection tests: ${reportSummary(g).tested?'Reported passed':'Unresolved'}\nExternal access: ${reportSummary(g).external?'Reported cleared':'Unresolved'}\nThese are self-reported checks, not independent verification.\n\n## Sources\n${g.sources.map(s=>`${s.title}: ${s.url}`).join('\n')}\n\nChecked: ${g.checked}. Status: ${g.status}\n`;const a=document.createElement('a');const object=URL.createObjectURL(new Blob([text],{type:'text/markdown'}));a.href=object;a.download=g.id.replace(/[^a-z0-9-]/gi,'-')+'-oauth-guide.md';a.click();setTimeout(()=>URL.revokeObjectURL(object),1000)}
document.addEventListener('click',e=>{const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return}const stepHandoff=e.target.closest('[data-step-handoff]');if(stepHandoff){openHandoff('step',Number(stepHandoff.dataset.stepHandoff));return}const blockerHandoff=e.target.closest('[data-blocker-handoff]');if(blockerHandoff){openHandoff('blocker',Number(blockerHandoff.dataset.blockerHandoff));return}const help=e.target.closest('[data-help]');if(help){stepHelp(Number(help.dataset.help));return}const guide=e.target.closest('[data-guide]');if(guide){const g=all().find(x=>x.id===guide.dataset.guide);if(g)openGuide(g);return}const filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b===filter);b.setAttribute('aria-pressed',String(b===filter))});renderCards();return}const step=e.target.closest('[data-step]');if(step&&state.selected){const current=effectiveGuide(state.selected),i=Number(step.dataset.step),k=progressKey(current,i);state.done[k]=!state.done[k];save('atlas-progress',state.done);step.setAttribute('aria-pressed',String(state.done[k]));step.innerHTML=state.done[k]?ico('check',23):`<span>${i+1}</span>`;step.closest('.step').classList.toggle('complete',state.done[k]);$('#progress').textContent=`${current.steps.filter((_,n)=>state.done[progressKey(current,n)]).length} / ${current.steps.length} checked by you`;$('#next-step-panel').innerHTML=nextStepPanel(current);const next=current.steps.findIndex((_,n)=>!state.done[progressKey(current,n)]);document.querySelectorAll('.step').forEach((el,n)=>el.classList.toggle('current',n===next));return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='start-setup'){const current=effectiveGuide(state.selected),i=current.steps.findIndex((_,n)=>!state.done[progressKey(current,n)]);document.getElementById('step-'+Math.max(i,0))?.scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('#step-'+Math.max(i,0)+' h3')?.focus({preventScroll:true});}if(action==='copy-handoff'){copyHandoff();return}if(action==='adapt-guide'){const g=effectiveGuide(state.selected);state.query=g.name;state.researchDefaults={audience:g.requestContext?.audience||'customers',operation:g.requestContext?.operation||(g.id==='gmail'&&activeScenario(g)==='send'?'write':'read'),authRoute:g.requestContext?.authRoute||'custom',purpose:g.goal};modal();return}if(action==='saved'){state.selected=null;state.view='library';state.filter='My research';state.query='';history.pushState({},'',location.pathname);shell();return}if(action==='readiness'){document.getElementById('readiness')?.scrollIntoView({behavior:'smooth'});return}if(action==='home'){state.filter='All apps';home();}if(action==='research')modal();if(action==='close')closeModal();if(action==='share')share();if(action==='export')download();if(action==='evidence'){state.selected=null;state.view='evidence';history.pushState({},'',location.pathname);shell();scrollTo(0,0)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&$('#search')){e.preventDefault();$('#search').focus()}if(e.key==='Tab'&&$('.modal')){const focus=[...$('.modal').querySelectorAll('button:not([disabled]),input,textarea,a[href]')];const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('popstate',route);route();fetch('/api/research').then(r=>r.json()).then(v=>{state.configured=v.configured===true;const requested=new URLSearchParams(location.search);if(state.configured&&requested.get('research')==='Linear'&&requested.get('run')==='1'){state.query='Linear';modal();$('textarea[name="purpose"]').value='Read project issues for external users through user-delegated OAuth; validate registration and external-user access';history.replaceState({},'',location.pathname);$('#research-operation').value='read';$('#research-audience').value='customers';$('#research-auth-route').value='custom';$('#research-form').requestSubmit();return}const m=$('.modal');if(m&&!state.busy){const a=$('#app-name')?.value,p=$('textarea')?.value;state.researchDefaults={audience:$('#research-audience')?.value,operation:$('#research-operation')?.value,authRoute:$('#research-auth-route')?.value,purpose:p};modal();$('#app-name').value=a||''}}).catch(()=>state.configured=false);

document.addEventListener('change',e=>{const key=e.target.dataset?.report;if(!key||!state.selected||!['configuration','consent','action','reconnect','external'].includes(key))return;const g=effectiveGuide(state.selected),value=key==='external'?e.target.value:e.target.checked;if(key==='external'&&!['unresolved','cleared','not-required'].includes(value))return;const k=reportKey(g);state.reports[k]={...reportFor(g),[key]:value,updatedAt:new Date().toISOString()};save('atlas-readiness',state.reports);guidePage(state.selected);document.querySelector('[data-report="'+key+'"]')?.focus()});
